package usageanalytics

import (
	"encoding/json"
	"math"
	"os"
	"strings"
	"testing"

	"github.com/stretchr/testify/require"
)

func TestCacheSampleMatchesCCHFixtures(t *testing.T) {
	// Expected bytes and hashes were generated by CCH 0c508eaa, not this port.
	data, err := os.ReadFile("testdata/cch-cache-fixtures.json")
	require.NoError(t, err)
	var fixtures struct {
		Cases []struct {
			Name, Format        string
			Body                json.RawMessage
			ExpectedTokens      int64
			ExpectedFingerprint string
		}
	}
	require.NoError(t, json.Unmarshal(data, &fixtures))
	for _, fixture := range fixtures.Cases {
		t.Run(fixture.Name, func(t *testing.T) {
			sample := CacheSampleFromRequest(fixture.Body, fixture.Format, 1, 42, "model")
			require.NotNil(t, sample)
			require.Equal(t, fixture.ExpectedTokens, sample.TheoreticalTokens)
			require.True(t, strings.HasSuffix(sample.CompatibilityKey, ":"+fixture.ExpectedFingerprint))
			if fixture.Name == "anthropic_media_and_thinking" {
				require.Equal(t, "1h", sample.TTLBucket)
			} else {
				require.Equal(t, "5m", sample.TTLBucket)
			}
		})
	}
}

func TestCacheSampleIsolationAndUnsupportedInput(t *testing.T) {
	body := []byte(`{"messages":[{"role":"user","content":"private prompt"}]}`)
	a := CacheSampleFromRequest(body, "openai/chat_completions", 1, 42, "model")
	b := CacheSampleFromRequest(body, "openai/chat_completions", 2, 42, "model")
	c := CacheSampleFromRequest(body, "openai/chat_completions", 1, 43, "model")
	require.NotEqual(t, a.CompatibilityKey, b.CompatibilityKey)
	require.NotEqual(t, a.CompatibilityKey, c.CompatibilityKey)
	require.NotContains(t, a.CompatibilityKey, "private prompt")
	require.Nil(t, CacheSampleFromRequest(body, "openai/embeddings", 1, 42, "model"))
	require.Nil(t, CacheSampleFromRequest([]byte(`{broken`), "openai/chat_completions", 1, 42, "model"))
}

func TestCacheCoefficientCCHIntegerThresholds(t *testing.T) {
	for _, test := range []struct {
		name                                     string
		samples, eligible, theoretical, observed int64
		want                                     int
	}{
		{"no samples", 0, 0, 0, 0, 0}, {"no theoretical", 10, 10, 0, 100, 0},
		{"four", 4, 4, 1000, 500, 500}, {"five", 5, 5, 1000, 500, 1500},
		{"twenty nine", 29, 29, 1000, 500, 1500}, {"thirty", 30, 30, 1000, 500, 3000},
		{"ninety nine", 99, 99, 1000, 500, 3000}, {"hundred", 100, 100, 1000, 500, 5000},
		{"observable fraction", 200, 100, 1000, 500, 2500}, {"integer truncation", 6, 5, 5000, 4000, 1999},
		{"clamped", 100, 100, 1000, 2000, 10000}, {"large sums", 100, 100, math.MaxInt64, math.MaxInt64, 10000},
	} {
		t.Run(test.name, func(t *testing.T) {
			require.Equal(t, test.want, CacheCoefficient(test.samples, test.eligible, test.theoretical, test.observed))
		})
	}
}
